import { MakeLogicType, kea, path } from 'kea'
import { loaders } from 'kea-loaders'
import { expectLogic } from 'kea-test-utils'
import posthog from 'posthog-js'

import { ApiError } from 'lib/api-error'
import { NEW_QUERY_STARTED_ERROR_MESSAGE } from 'lib/utils/kea-logic-builders'

import { initKeaTests } from '~/test/init'

let loaderFailure: unknown

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface failingLoaderLogicValues {
    thing: string | null
    thingLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface failingLoaderLogicActions {
    loadThing: () => any
    loadThingFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadThingSuccess: (
        thing: never,
        payload?: any
    ) => {
        thing: never
        payload?: any
    }
}

export type failingLoaderLogicType = MakeLogicType<failingLoaderLogicValues, failingLoaderLogicActions>

const failingLoaderLogic = kea<failingLoaderLogicType>([
    path(['initKeaTestFailingLoader']),
    loaders({
        thing: [
            null as string | null,
            {
                loadThing: async () => {
                    throw loaderFailure
                },
            },
        ],
    }),
])

describe('initKea', () => {
    let captureException: jest.SpyInstance

    beforeEach(() => {
        initKeaTests()
        captureException = jest.spyOn(posthog, 'captureException').mockImplementation()
        jest.spyOn(console, 'error').mockImplementation()
    })

    afterEach(() => {
        jest.restoreAllMocks()
    })

    it.each([
        ['skips a request the logic cancelled itself', new Error(NEW_QUERY_STARTED_ERROR_MESSAGE), 0],
        // The message reads like a cancellation but the request really failed, so it stays reportable.
        ['reports a server failure that mentions an abort', new ApiError('current transaction is aborted', 500), 1],
    ])('%s', async (_name, failure, expectedCaptures) => {
        loaderFailure = failure
        const logic = failingLoaderLogic()
        logic.mount()

        await expectLogic(logic, () => logic.actions.loadThing()).toDispatchActions(['loadThingFailure'])

        expect(captureException).toHaveBeenCalledTimes(expectedCaptures)
        logic.unmount()
    })
})
